CREATE OR REPLACE FUNCTION public.normalize_public_title_pipes() RETURNS TRIGGER AS $$ BEGIN IF NEW.title IS NOT NULL THEN NEW.title := regexp_replace(NEW.title, '\s*[—–]\s*', ' | ', 'g'); NEW.title := regexp_replace(NEW.title, '(\s*\|\s*){2,}', ' | ', 'g'); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql SET search_path = public; DROP TRIGGER IF EXISTS normalize_title_pipes ON public.content_pages; CREATE TRIGGER normalize_title_pipes BEFORE INSERT OR UPDATE ON public.content_pages FOR EACH ROW EXECUTE FUNCTION public.normalize_public_title_pipes(); DROP TRIGGER IF EXISTS normalize_title_pipes ON public.news_articles; CREATE TRIGGER normalize_title_pipes BEFORE INSERT OR UPDATE ON public.news_articles FOR EACH ROW EXECUTE FUNCTION public.normalize_public_title_pipes(); DROP TRIGGER IF EXISTS normalize_title_pipes ON public.guides; CREATE TRIGGER normalize_title_pipes BEFORE INSERT OR UPDATE ON public.guides FOR EACH ROW EXECUTE FUNCTION public.normalize_public_title_pipes(); UPDATE public.content_pages SET title = regexp_replace(regexp_replace(title, '\s*[—–]\s*', ' | ', 'g'), '(\s*\|\s*){2,}', ' | ', 'g') WHERE title ~ '[—–]'; UPDATE public.news_articles SET title = regexp_replace(regexp_replace(title, '\s*[—–]\s*', ' | ', 'g'), '(\s*\|\s*){2,}', ' | ', 'g') WHERE title ~ '[—–]'; UPDATE public.guides SET title = regexp_replace(regexp_replace(title, '\s*[—–]\s*', ' | ', 'g'), '(\s*\|\s*){2,}', ' | ', 'g') WHERE title ~ '[—–]';